"""Self-check for gradle_verification_variants.py without network access.

Pins the rewrite: a Portal copy that differs from the recorded checksum becomes <also-trust> next to
the existing value, a second run adds nothing, and files the Portal leaves to Central stay untouched.
"""

import hashlib
import importlib.util
import sys
from pathlib import Path

SCRIPT = Path(__file__).resolve().parent / "gradle_verification_variants.py"
SPEC = importlib.util.spec_from_file_location("gradle_verification_variants", SCRIPT)
variants = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(variants)

CENTRAL_POM = b"<project>central</project>"
PORTAL_POM = b"<project>portal</project>"


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


METADATA = f"""<?xml version="1.0" encoding="UTF-8"?>
<verification-metadata xmlns="https://schema.gradle.org/dependency-verification">
   <components>
      <component group="org.example" name="marker" version="1.0">
         <artifact name="marker-1.0.pom">
            <sha256 value="{sha(CENTRAL_POM)}" origin="Generated by Gradle"/>
         </artifact>
      </component>
      <component group="org.example" name="lib" version="2.0">
         <artifact name="lib-2.0.jar">
            <sha256 value="{"a" * 64}" origin="Generated by Gradle"/>
         </artifact>
      </component>
   </components>
</verification-metadata>
"""


def run(monkeypatch, path: Path) -> None:
    def portal_copy(url):
        return PORTAL_POM if url.endswith("marker-1.0.pom") else None

    def fetch(opener, url):
        return (200, CENTRAL_POM) if url.endswith("marker-1.0.pom") else (404, b"")

    monkeypatch.setattr(variants, "portal_copy", portal_copy)
    monkeypatch.setattr(variants, "fetch", fetch)
    monkeypatch.setattr(sys, "argv", ["gradle_verification_variants.py", str(path)])
    variants.main()


def test_portal_variant_becomes_also_trust_once(tmp_path, monkeypatch):
    path = tmp_path / "verification-metadata.xml"
    path.write_text(METADATA, encoding="utf-8")

    run(monkeypatch, path)
    first = path.read_text(encoding="utf-8")
    assert (
        f'            <sha256 value="{sha(CENTRAL_POM)}" origin="Generated by Gradle">\n'
        f'               <also-trust value="{sha(PORTAL_POM)}"/>\n'
        "            </sha256>\n"
    ) in first
    assert f'<sha256 value="{"a" * 64}" origin="Generated by Gradle"/>' in first

    run(monkeypatch, path)
    assert path.read_text(encoding="utf-8") == first
